// План specs/signup-email-confirm.md, 1.1 (кейс SU-04). Гость на PROD. Только чтение: форму не заполняем и не отправляем. @prod-safe
import { test, expect } from '@playwright/test';

test.describe('Регистрация — входная точка (#d0392fa9)', () => {
  test('Register page with referral code shows the sign-up form #d0392fa9 @desktop @prod-safe', async ({ page }) => {
    await page.addInitScript(() => {
      try { window.localStorage.setItem('preferred-language', 'en'); } catch { /* ignore */ }
    });
    await page.goto('/register?ref=NG34ESMA');

    await expect(page.getByRole('heading', { name: 'Company Admin Sign-Up' })).toBeVisible();
    expect(new URL(page.url()).pathname).toBe('/register');
    expect(new URL(page.url()).searchParams.get('ref')).toBe('NG34ESMA');

    for (const field of ['Full Name', 'Email', 'Phone Number', 'Password', 'Confirm Password', 'Company Name']) {
      await expect(page.getByRole('textbox', { name: field, exact: true }), `поле ${field}`).toBeVisible();
    }

    const signUp = page.getByRole('button', { name: 'Sign Up', exact: true });
    await expect(signUp).toBeVisible();
    await expect(signUp).toBeEnabled();
    await expect(page.getByRole('link', { name: 'Sign In', exact: true })).toHaveAttribute('href', /\/login$/);
  });
});
